// В файле src/context/AuthContext.js

  // Регистрация через API (отправляем как FormData)
  const register = useCallback(async (userData) => {
    try {
      // Создаем объект FormData
      const formData = new FormData();
      formData.append('username', userData.username);
      formData.append('email', userData.email);
      formData.append('password', userData.password);

      // Делаем специальный POST-запрос с FormData
      const response = await fetch('https://luna-aurea.ru/api/index.php?route=register', {
        method: 'POST',
        body: formData, // Важно: НЕ ставим header Content-Type, браузер установит его сам с правильной границей
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Registration failed');
      }

      const { token: authToken, user: newUser } = data;
      setToken(authToken);
      setUser(newUser);
      setCart([]);
      setFavorites([]);

      localStorage.setItem('auth_token', authToken);
      localStorage.setItem('auth_user', JSON.stringify(newUser));

      return { user: newUser, token: authToken };
    } catch (error) {
      console.error('Registration error:', error);
      throw error;
    }
  }, []);

  // Вход через API (отправляем как FormData)
  const login = useCallback(async (email, password) => {
    try {
      const formData = new FormData();
      formData.append('email', email);
      formData.append('password', password);

      const response = await fetch('https://luna-aurea.ru/api/index.php?route=login', {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Login failed');
      }

      const { token: authToken, user: loggedInUser } = data;
      setToken(authToken);
      setUser(loggedInUser);

      localStorage.setItem('auth_token', authToken);
      localStorage.setItem('auth_user', JSON.stringify(loggedInUser));

      // Загружаем корзину (если нужно)
      // await loadUserData();

      return { user: loggedInUser, token: authToken };
    } catch (error) {
      console.error('Login error:', error);
      throw error;
    }
  }, []);
